    <script>
        window.speakingMeetingApp = function speakingMeetingApp() {
            return {
                activeTab: 'materi',
                previewRole: (function() {
                    @if(!Auth::user()?->isAdmin() && !Auth::user()?->isTeacher())
                        return 'student';
                    @else
                        try {
                            return localStorage.getItem('tb_speaking_view_role') || 'admin';
                        } catch(e) {
                            return 'admin';
                        }
                    @endif
                })(),
                assignedStudentRole: '{{ $myAssignedRole }}',
                setPreviewRole(role) {
                    this.previewRole = role;
                    try {
                        localStorage.setItem('tb_speaking_view_role', role);
                    } catch(e) {}
                    if (role === 'student') {
                        this.gameViewMode = 'student';
                    }
                    window.dispatchEvent(new CustomEvent('preview-role-changed', { detail: role }));
                },
                // Which subtopic block is active in the Materi tab and which
                // game is active in the Game Speaking tab - lifted to root
                // scope (rather than tab-local) so switching one can keep
                // the other in sync for meetings with multiple subtopics.
                activeMateriIndex: 0,
                activeGameIndex: 0,
                showAllPartneringEn: false,
                showTranscript: true,
                isPlaying: false,
                speechRate: 1.0,
                availableVoices: [],

                // Global game sub-tab tracking for floating admin dock
                weddingGameTab: 'worksheet',
                kitchenActiveStudent: 'A',
                kitchenShowAnswers: false,
                touristTab: 'map',
                touristSheet: 'sheet_a',
                selectedGroupPreview: null,
                // Generic pair/group slot for any future game mechanic that
                // doesn't have its own bespoke admin bar branch yet - see
                // setGenericSlot() below.
                genericActiveSlot: null,
                activeSubtopicId: null,
                activeSubtopicIndex: 0,

                init() {
                    this.preloadVoices();
                    if ('speechSynthesis' in window) {
                        window.speechSynthesis.onvoiceschanged = () => {
                            this.preloadVoices();
                        };
                    }
                    window.addEventListener('wedding-tab-updated', (e) => {
                        if (e.detail) this.weddingGameTab = e.detail;
                    });
                    window.addEventListener('kitchen-student-updated', (e) => {
                        if (e.detail) this.kitchenActiveStudent = e.detail;
                    });
                    window.addEventListener('kitchen-answers-updated', (e) => {
                        this.kitchenShowAnswers = !!e.detail;
                    });
                    window.addEventListener('tourist-view-updated', (e) => {
                        if (e.detail) {
                            if (e.detail.tab) this.touristTab = e.detail.tab;
                            if (e.detail.sheet) this.touristSheet = e.detail.sheet;
                        }
                    });
                },

                setWeddingGameTab(tab, groupId = null) {
                    this.weddingGameTab = tab;
                    if (groupId !== null) {
                        this.selectedGroupPreview = (this.selectedGroupPreview === groupId) ? null : groupId;
                    } else {
                        this.selectedGroupPreview = null;
                    }
                    this.activeTab = 'game';
                    // Auto-select wedding game index if present
                    if (Array.isArray(this.meetingGames)) {
                        const wpIdx = this.meetingGames.findIndex(g => (g && g.type === 'wedding_photos'));
                        if (wpIdx !== -1) {
                            this.activeGameIndex = wpIdx;
                        }
                    } else {
                        @php
                            $wpIndex = collect($games)->search(fn($g) => ($g['type'] ?? '') === 'wedding_photos');
                        @endphp
                        @if($wpIndex !== false && $wpIndex !== null)
                            this.activeGameIndex = {{ $wpIndex }};
                        @endif
                    }
                    window.dispatchEvent(new CustomEvent('set-wedding-tab', { detail: tab }));
                },

                setKitchenGameTab(slot, groupId = null) {
                    this.kitchenActiveStudent = slot;
                    if (groupId !== null) {
                        this.selectedGroupPreview = (this.selectedGroupPreview === groupId) ? null : groupId;
                    } else {
                        this.selectedGroupPreview = null;
                    }
                    this.activeTab = 'game';
                    @php
                        $kgIndex = collect($games)->search(fn($g) => ($g['type'] ?? '') === 'how_many_kitchen');
                    @endphp
                    @if($kgIndex !== false && $kgIndex !== null)
                        this.activeGameIndex = {{ $kgIndex }};
                    @endif
                    window.dispatchEvent(new CustomEvent('set-kitchen-student', { detail: slot }));
                },

                toggleKitchenAnswers() {
                    this.kitchenShowAnswers = !this.kitchenShowAnswers;
                    @php
                        $kgIndex = collect($games)->search(fn($g) => ($g['type'] ?? '') === 'how_many_kitchen');
                    @endphp
                    @if($kgIndex !== false && $kgIndex !== null)
                        this.activeGameIndex = {{ $kgIndex }};
                    @endif
                    window.dispatchEvent(new CustomEvent('toggle-kitchen-answers', { detail: this.kitchenShowAnswers }));
                },

                setTouristTab(tab, sheet = 'sheet_a', groupId = null) {
                    this.touristTab = tab;
                    if (sheet) this.touristSheet = sheet;
                    if (groupId !== null) {
                        this.selectedGroupPreview = (this.selectedGroupPreview === groupId) ? null : groupId;
                    } else {
                        this.selectedGroupPreview = null;
                    }
                    this.activeTab = 'game';
                    window.dispatchEvent(new CustomEvent('set-tourist-view', { detail: { tab, sheet: this.touristSheet } }));
                },

                /**
                 * Generic pair/group slot switcher for any game mechanic
                 * without its own bespoke admin bar branch (wedding_photos,
                 * how_many_kitchen and tourist_in_town each have their own
                 * setXxxTab() above since their worksheet content needs
                 * mechanic-specific state). A future mechanic can listen for
                 * 'generic-slot-updated' the same way the existing branches
                 * listen for their own set-*-tab events.
                 */
                setGenericSlot(slot, groupId = null) {
                    this.genericActiveSlot = slot;
                    if (groupId !== null) {
                        this.selectedGroupPreview = (this.selectedGroupPreview === groupId) ? null : groupId;
                    } else {
                        this.selectedGroupPreview = null;
                    }
                    this.activeTab = 'game';
                    window.dispatchEvent(new CustomEvent('generic-slot-updated', { detail: slot }));
                },

                goToSubtopic(target, tab = null, materiIndex = 0, subTab = null) {
                    if (typeof target === 'number') {
                        this.activeSubtopicIndex = target;
                        this.activeMateriIndex = target;
                        this.activeGameIndex = target;
                    } else if (typeof target === 'string') {
                        this.activeSubtopicId = target;
                        if (materiIndex !== undefined && materiIndex !== null) {
                            this.activeSubtopicIndex = Number(materiIndex);
                            this.activeMateriIndex = Number(materiIndex);
                            this.activeGameIndex = Number(materiIndex);
                        }
                    }
                    if (tab && this.activeTab !== tab) {
                        this.activeTab = tab;
                    }
                    if (subTab) {
                        window.dispatchEvent(new CustomEvent('set-pronoun-subtab', { detail: subTab }));
                        window.dispatchEvent(new CustomEvent('set-time-tab', { detail: subTab }));
                    }
                    this.$nextTick(() => {
                        const targetId = typeof target === 'string' ? target : ('sec-m' + (typeof meetingNumber !== 'undefined' ? meetingNumber : '') + '-sub-' + (Number(target) + 1));
                        const el = document.getElementById(targetId) || (typeof target === 'string' ? document.getElementById(target) : null);
                        if (el) {
                            el.scrollIntoView({ behavior: 'smooth', block: 'start' });
                            el.classList.add('ring-4', 'ring-[#29a8f5]', 'ring-offset-4', 'transition-all', 'duration-500');
                            setTimeout(() => {
                                el.classList.remove('ring-4', 'ring-[#29a8f5]', 'ring-offset-4');
                            }, 2500);
                        }
                    });
                },

                preloadVoices() {
                    if (!('speechSynthesis' in window)) return;
                    const v = window.speechSynthesis.getVoices();
                    if (v && v.length > 0) {
                        this.availableVoices = v;
                    }
                },

                getBestVoice(gender = 'male') {
                    const voices = this.availableVoices.length > 0 ? this.availableVoices : (('speechSynthesis' in window) ? window.speechSynthesis.getVoices() : []);
                    if (!voices || voices.length === 0) return null;

                    const maleIdentifiers = [
                        'google uk english male',
                        'guy',
                        'daniel',
                        'david',
                        'christopher',
                        'eric',
                        'george',
                        'oliver',
                        'tom',
                        'james',
                        'alex',
                        'rishi',
                        'arthur',
                        'mark',
                        'richard',
                        'fred'
                    ];

                    const femaleIdentifiers = [
                        'google us english',
                        'google uk english female',
                        'jenny',
                        'samantha',
                        'ava',
                        'aria',
                        'karen',
                        'moira',
                        'victoria',
                        'serena',
                        'kate',
                        'siri'
                    ];

                    if (gender === 'male') {
                        // 1. Check for specific male voice names
                        for (const name of maleIdentifiers) {
                            const found = voices.find(v => v.name.toLowerCase().includes(name) && (v.lang.startsWith('en-US') || v.lang.startsWith('en-GB') || v.lang.startsWith('en')));
                            if (found) return found;
                        }
                        // 2. Check if voice name doesn't contain female names and is en
                        const nonFemale = voices.find(v => v.lang.startsWith('en') && !femaleIdentifiers.some(fn => v.name.toLowerCase().includes(fn)));
                        if (nonFemale) return nonFemale;
                    } else {
                        // Female voice lookup
                        for (const name of femaleIdentifiers) {
                            const found = voices.find(v => v.name.toLowerCase().includes(name) && (v.lang.startsWith('en-US') || v.lang.startsWith('en-GB') || v.lang.startsWith('en')));
                            if (found) return found;
                        }
                    }

                    // Fallback to standard English
                    return voices.find(v => v.lang.startsWith('en-US') || v.lang.startsWith('en-GB') || v.lang.startsWith('en')) || null;
                },

                audioPlayer: null,

                stopAllAudio() {
                    if (this.audioPlayer) {
                        this.audioPlayer.pause();
                        this.audioPlayer.currentTime = 0;
                    }
                    if ('speechSynthesis' in window) {
                        window.speechSynthesis.cancel();
                    }
                    this.isPlaying = false;
                },

                playAudioUrl(audioUrl, fallbackScript) {
                    if (this.isPlaying) {
                        this.stopAllAudio();
                        return;
                    }
                    this.stopAllAudio();
                    if (audioUrl && audioUrl.length > 5) {
                        if (!this.audioPlayer) {
                            this.audioPlayer = new Audio();
                        }
                        this.audioPlayer.src = audioUrl;
                        this.audioPlayer.playbackRate = this.speechRate;
                        this.audioPlayer.onplay = () => { this.isPlaying = true; };
                        this.audioPlayer.onended = () => { this.isPlaying = false; };
                        this.audioPlayer.onerror = () => {
                            this.isPlaying = false;
                            this.playListeningDialogue(fallbackScript);
                        };
                        this.audioPlayer.play().catch(() => {
                            this.playListeningDialogue(fallbackScript);
                        });
                    } else {
                        this.playListeningDialogue(fallbackScript);
                    }
                },

                playTurnAudio(audioUrl, text, gender = 'male') {
                    if (this.isPlaying) {
                        this.stopAllAudio();
                        return;
                    }
                    this.stopAllAudio();
                    if (audioUrl && audioUrl.length > 5) {
                        if (!this.audioPlayer) {
                            this.audioPlayer = new Audio();
                        }
                        this.audioPlayer.src = audioUrl;
                        this.audioPlayer.playbackRate = this.speechRate;
                        this.audioPlayer.onplay = () => { this.isPlaying = true; };
                        this.audioPlayer.onended = () => { this.isPlaying = false; };
                        this.audioPlayer.onerror = () => {
                            this.isPlaying = false;
                            this.speakText(text, gender);
                        };
                        this.audioPlayer.play().catch(() => {
                            this.speakText(text, gender);
                        });
                    } else {
                        this.speakText(text, gender);
                    }
                },

                setSpeed(speed) {
                    this.speechRate = speed;
                    this.stopAllAudio();
                },

                prepareSpeechText(text) {
                    if (!text) return '';
                    let clean = text.replace(/\[.*?\]/g, '').replace(/["“”]/g, '').trim();

                    // Convert any letter spelling pattern like "W. R. I. G. H. T" or "W.R.I.G.H.T" or "W-R-I-G-H-T"
                    // into comma-separated letters: "W, R, I, G, H, T." so the browser speech engine pauses on every single letter!
                    clean = clean.replace(/\b([A-Za-z](?:[\.\-\s]+[A-Za-z])+)\b/g, (match) => {
                        const letters = match.replace(/[^A-Za-z]/g, '');
                        if (match.includes('.') || match.includes('-') || (match.includes(' ') && letters.length >= 2 && letters === letters.toUpperCase())) {
                            const chars = letters.split('');
                            if (chars.length >= 2) {
                                return chars.map(l => l.toUpperCase()).join(', ') + '.';
                            }
                        }
                        return match;
                    });

                    return clean;
                },

                speakText(text, gender = 'male') {
                    this.stopAllAudio();
                    if (!text || !('speechSynthesis' in window)) return;

                    const cleanText = this.prepareSpeechText(text);
                    if (!cleanText) return;

                    window.speechSynthesis.cancel();
                    const utterance = new SpeechSynthesisUtterance(cleanText);
                    utterance.lang = 'en-US';
                    utterance.rate = this.speechRate * 0.90;
                    utterance.pitch = (gender === 'male') ? 0.94 : 1.08;

                    const voice = this.getBestVoice(gender);
                    if (voice) {
                        utterance.voice = voice;
                    }

                    utterance.onstart = () => { this.isPlaying = true; };
                    utterance.onend = () => { this.isPlaying = false; };
                    utterance.onerror = () => { this.isPlaying = false; };

                    window.speechSynthesis.speak(utterance);
                },

                togglePlayAudio(scriptText, gender = 'male') {
                    if (this.isPlaying) {
                        this.stopAllAudio();
                        return;
                    }

                    this.stopAllAudio();
                    if (!scriptText || !('speechSynthesis' in window)) return;

                    const cleanText = this.prepareSpeechText(scriptText);
                    if (!cleanText) return;

                    // Cleanly split transcript into sentences
                    const sentences = cleanText.match(/[^.!?\n]+[.!?\n]*/g) || [cleanText];
                    let sentenceIdx = 0;
                    this.isPlaying = true;

                    const playNextSentence = () => {
                        if (!this.isPlaying || sentenceIdx >= sentences.length) {
                            this.isPlaying = false;
                            return;
                        }

                        const currentSentence = sentences[sentenceIdx].trim();
                        sentenceIdx++;
                        if (!currentSentence) {
                            playNextSentence();
                            return;
                        }

                        window.speechSynthesis.cancel();
                        const utterance = new SpeechSynthesisUtterance(currentSentence);
                        utterance.lang = 'en-US';
                        utterance.rate = this.speechRate * 0.90;
                        utterance.pitch = (gender === 'male') ? 0.94 : 1.08;

                        const voice = this.getBestVoice(gender);
                        if (voice) {
                            utterance.voice = voice;
                        }

                        utterance.onend = () => {
                            if (this.isPlaying) {
                                setTimeout(playNextSentence, 220); // Natural human breathing pause
                            }
                        };
                        utterance.onerror = () => {
                            if (this.isPlaying) {
                                playNextSentence();
                            }
                        };

                        window.speechSynthesis.speak(utterance);
                    };

                    playNextSentence();
                },

                playFullDialogue() {
                    if (this.isPlaying) {
                        this.stopAllAudio();
                        return;
                    }
                    this.stopAllAudio();

                    const dialogues = @js($meetingData['dialogue'] ?? []);
                    if (!dialogues || dialogues.length === 0 || !('speechSynthesis' in window)) return;

                    let idx = 0;
                    this.isPlaying = true;

                    const playNextTurn = () => {
                        if (!this.isPlaying || idx >= dialogues.length) {
                            this.isPlaying = false;
                            return;
                        }

                        const current = dialogues[idx];
                        idx++;
                        const rawText = current.en || current.text || '';
                        const cleanText = this.prepareSpeechText(rawText);
                        if (!cleanText) {
                            playNextTurn();
                            return;
                        }

                        const speaker = (current.speaker || '').toLowerCase();
                        const femaleKeywords = ['sarah', 'woman', 'girl', 'anna', 'linda', 'mary', 'jane', 'speaker b', 'student b', 'receptionist'];
                        const gender = femaleKeywords.some(k => speaker.includes(k)) ? 'female' : 'male';

                        window.speechSynthesis.cancel();
                        const utterance = new SpeechSynthesisUtterance(cleanText);
                        utterance.lang = 'en-US';
                        utterance.rate = this.speechRate * 0.90;
                        utterance.pitch = (gender === 'male') ? 0.94 : 1.08;

                        const voice = this.getBestVoice(gender);
                        if (voice) {
                            utterance.voice = voice;
                        }

                        utterance.onend = () => {
                            if (this.isPlaying) {
                                setTimeout(playNextTurn, 350); // Natural pause between speakers
                            }
                        };
                        utterance.onerror = () => {
                            if (this.isPlaying) {
                                playNextTurn();
                            }
                        };

                        window.speechSynthesis.speak(utterance);
                    };

                    playNextTurn();
                },

                playListeningDialogue(rawScript) {
                    if (this.isPlaying) {
                        this.stopAllAudio();
                        return;
                    }
                    this.stopAllAudio();
                    if (!rawScript || !('speechSynthesis' in window)) return;

                    // Detect dialogue speaker turns
                    let turns = rawScript.split(/\r?\n/).map(t => t.trim()).filter(t => t.length > 0);
                    if (turns.length <= 1 && /(?:[A-Za-z0-9\.\s]{2,25}):/i.test(rawScript)) {
                        turns = rawScript.split(/(?=(?:[A-Z][A-Za-z0-9\.\s]{1,25}):\s*)/i).map(t => t.trim()).filter(t => t.length > 0);
                    }

                    if (turns.length === 0) return;

                    let turnIdx = 0;
                    this.isPlaying = true;

                    const playNextTurn = () => {
                        if (!this.isPlaying || turnIdx >= turns.length) {
                            this.isPlaying = false;
                            return;
                        }

                        const rawTurn = turns[turnIdx].trim();
                        turnIdx++;
                        if (!rawTurn) {
                            playNextTurn();
                            return;
                        }

                        const parts = rawTurn.split(/:\s*(.+)/s);
                        let speaker = '';
                        let spokenText = rawTurn;

                        if (parts.length >= 2) {
                            speaker = parts[0].trim().toLowerCase();
                            spokenText = parts[1].trim();
                        }

                        // Clean text: strip role name and format spelled letters like W-R-I-G-H-T to W. R. I. G. H. T.
                        const cleanText = this.prepareSpeechText(spokenText).replace(/\\'/g, "'");
                        if (!cleanText) {
                            playNextTurn();
                            return;
                        }

                        // Determine voice gender:
                        const isFemale = ['receptionist', 'female', 'woman', 'sophia', 'sarah', 'linda', 'mary', 'sari', 'maya', 'putri', 'dewi', 'anita', 'emma', 'jessica', 'student b', 'waitress', 'customer', 'shopper'].some(k => speaker.includes(k));
                        const gender = isFemale ? 'female' : 'male';

                        window.speechSynthesis.cancel();
                        const utterance = new SpeechSynthesisUtterance(cleanText);
                        utterance.lang = 'en-US';
                        utterance.rate = this.speechRate * 0.90;
                        utterance.pitch = (gender === 'male') ? 0.94 : 1.08;

                        const voice = this.getBestVoice(gender);
                        if (voice) {
                            utterance.voice = voice;
                        }

                        utterance.onend = () => {
                            if (this.isPlaying) {
                                setTimeout(playNextTurn, 320); // Natural conversation pause
                            }
                        };
                        utterance.onerror = () => {
                            if (this.isPlaying) {
                                playNextTurn();
                            }
                        };

                        window.speechSynthesis.speak(utterance);
                    };

                    playNextTurn();
                },

                // Alphabet & Spelling Drills
                spellWordAloud(word) {
                    if (!word) return;
                    const cleanWord = word.trim().toUpperCase();
                    const letters = cleanWord.split('').filter(char => /[A-Z]/.test(char));
                    if (letters.length === 0) return;
                    const spellingText = letters.join('. ') + '. ' + cleanWord;
                    this.speakText(spellingText, 'female');
                },

                // Classroom Game State (Worksheet 1b)
                gameCards: @js($games[0]['cards'] ?? []),
                selectedStudentCard: null,
                gameViewMode: 'student',
                isDrawing: false,
                surveyNameInput: '',
                surveyAnswerInput: '',
                surveyResponses: [],

                drawRandomCard() {
                    this.isDrawing = true;
                    setTimeout(() => {
                        if (this.gameCards && this.gameCards.length > 0) {
                            const randomIndex = Math.floor(Math.random() * this.gameCards.length);
                            this.selectedStudentCard = this.gameCards[randomIndex];
                        }
                        this.isDrawing = false;
                        this.gameViewMode = 'student';
                    }, 350);
                },

                selectCardById(id) {
                    this.selectedStudentCard = this.gameCards.find(c => c.id === parseInt(id)) || null;
                    this.gameViewMode = 'student';
                },

                addSurveyResponse() {
                    if (!this.surveyNameInput.trim() || !this.surveyAnswerInput.trim()) {
                        alert('Harap masukkan Nama Teman dan Jawabannya.');
                        return;
                    }
                    this.surveyResponses.push({
                        id: Date.now(),
                        name: this.surveyNameInput.trim(),
                        answer: this.surveyAnswerInput.trim()
                    });
                    this.surveyNameInput = '';
                    this.surveyAnswerInput = '';
                },

                removeSurveyResponse(id) {
                    this.surveyResponses = this.surveyResponses.filter(r => r.id !== id);
                },

                getReportText() {
                    if (!this.selectedStudentCard) return 'Pilih atau acak kartu misi Anda terlebih dahulu.';
                    if (this.surveyResponses.length === 0) {
                        return "In our class, my mission is: " + (this.selectedStudentCard.title || 'Classroom Survey') + ". I am surveying my classmates right now.";
                    }
                    const summary = this.surveyResponses.map(r => r.name + ' answered: "' + r.answer + '"').join(', ');
                    const topic = this.selectedStudentCard.badge || this.selectedStudentCard.title || 'our topic';
                    return "In our group, I asked " + this.surveyResponses.length + " classmates about " + topic + ". " + summary + ". Based on my survey, " + this.surveyResponses[0].answer + " is a popular answer!";
                },

                // AI Voice Interview State
                aiQuestions: @js($meetingData['ai_interview'] ?? [
                    [
                        'id' => 1,
                        'question' => "Hello! Welcome to your speaking practice session. Let's start with an introduction: What is your full name, and what should I call you?",
                        'hint' => "Answer: 'Hello! My full name is [Name], and you can call me [Nickname].'",
                    ],
                    [
                        'id' => 2,
                        'question' => "Nice to meet you! Where are you originally from, and where do you live right now?",
                        'hint' => "Answer: 'I am from [City/Country], and I currently live in [City].'",
                    ],
                    [
                        'id' => 3,
                        'question' => "Great! What is your current job or daily activity? Are you a student or are you working?",
                        'hint' => "Answer: 'I am a student at [School/University] / I work as a [Job].'",
                    ],
                    [
                        'id' => 4,
                        'question' => "Interesting! What do you usually like doing in your free time or on weekends?",
                        'hint' => "Answer: 'In my free time, I really enjoy [reading / playing sports / watching movies].'",
                    ],
                    [
                        'id' => 5,
                        'question' => "Wonderful! Why do you want to learn and improve your English speaking skills?",
                        'hint' => "Answer: 'I want to improve my English because [for my career / study / travel abroad].'",
                    ],
                ]),
                currentAiQIdx: 0,
                aiState: 'idle', // 'idle', 'speaking', 'listening', 'finished'
                showQuestionText: false,
                userSpokenText: '',
                recognitionInstance: null,

                // Admin-only "Edit Pertanyaan" modal state (see the modal
                // markup further down this file). aiEditDraft is a working
                // copy - aiQuestions itself (what the interview actually
                // reads from) is only replaced once a save succeeds.
                showAiEditModal: false,
                aiEditDraft: [],
                aiEditSaving: false,
                aiEditError: '',

                openAiEditModal() {
                    this.aiEditDraft = JSON.parse(JSON.stringify(this.aiQuestions));
                    this.aiEditError = '';
                    this.showAiEditModal = true;
                },

                saveAiInterviewQuestions() {
                    const cleaned = this.aiEditDraft
                        .map(q => ({ question: (q.question || '').trim(), hint: (q.hint || '').trim() }))
                        .filter(q => q.question !== '');

                    if (cleaned.length === 0) {
                        this.aiEditError = 'Minimal harus ada 1 pertanyaan dengan teks yang diisi.';
                        return;
                    }

                    this.aiEditSaving = true;
                    this.aiEditError = '';

                    fetch('{{ route('admin.speaking.ai-interview.update', ['level' => $level, 'meeting' => $meetingNumber]) }}', {
                        method: 'PUT',
                        headers: {
                            'Content-Type': 'application/json',
                            'Accept': 'application/json',
                            'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]')?.getAttribute('content') || '',
                            'X-Requested-With': 'XMLHttpRequest',
                        },
                        body: JSON.stringify({ questions: cleaned }),
                    })
                    .then(res => res.json().then(data => ({ ok: res.ok, data })))
                    .then(({ ok, data }) => {
                        if (!ok || !data.success) {
                            throw new Error(data.message || 'Gagal menyimpan pertanyaan.');
                        }
                        this.aiQuestions = data.questions;
                        this.currentAiQIdx = 0;
                        this.showAiEditModal = false;
                    })
                    .catch(err => {
                        this.aiEditError = err.message || 'Gagal menyimpan pertanyaan.';
                    })
                    .finally(() => {
                        this.aiEditSaving = false;
                    });
                },

                resetAiInterviewQuestionsToDefault() {
                    if (!confirm('Kembalikan pertanyaan AI Interview meeting ini ke versi default?')) return;

                    this.aiEditSaving = true;
                    this.aiEditError = '';

                    fetch('{{ route('admin.speaking.ai-interview.reset', ['level' => $level, 'meeting' => $meetingNumber]) }}', {
                        method: 'DELETE',
                        headers: {
                            'Accept': 'application/json',
                            'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]')?.getAttribute('content') || '',
                            'X-Requested-With': 'XMLHttpRequest',
                        },
                    })
                    .then(res => res.json().then(data => ({ ok: res.ok, data })))
                    .then(({ ok, data }) => {
                        if (!ok || !data.success) {
                            throw new Error('Gagal mereset pertanyaan.');
                        }
                        // Simplest reliable way to show the true default
                        // content again - it's only ever computed
                        // server-side at initial render, not duplicated in
                        // this Alpine state as a separate fallback value.
                        window.location.reload();
                    })
                    .catch(err => {
                        this.aiEditSaving = false;
                        this.aiEditError = err.message || 'Gagal mereset pertanyaan.';
                    });
                },

                get currentAiQuestion() {
                    return this.aiQuestions[this.currentAiQIdx] || null;
                },

                startAiInterview() {
                    this.currentAiQIdx = 0;
                    this.userSpokenText = '';
                    this.askCurrentAiQuestion();
                },

                toggleAiInteraction() {
                    if (this.aiState === 'idle') {
                        this.startAiInterview();
                    } else if (this.aiState === 'speaking') {
                        this.stopAllAudio();
                        this.aiState = 'listening';
                        this.startSpeechRecognition();
                    } else if (this.aiState === 'listening') {
                        this.stopSpeechRecognition();
                        this.nextAiQuestion();
                    } else if (this.aiState === 'finished') {
                        this.restartAiInterview();
                    }
                },

                askCurrentAiQuestion() {
                    const qObj = this.currentAiQuestion;
                    if (!qObj) {
                        this.aiState = 'finished';
                        this.speakText("Thank you so much! You did an outstanding job in this interview. Keep practicing your English speaking every day!", 'female');
                        return;
                    }

                    this.aiState = 'speaking';
                    this.userSpokenText = '';
                    this.stopAllAudio();

                    if ('speechSynthesis' in window) {
                        window.speechSynthesis.cancel();
                        const utterance = new SpeechSynthesisUtterance(qObj.question);
                        utterance.lang = 'en-US';
                        utterance.rate = this.speechRate * 0.92;
                        utterance.pitch = 1.05;

                        const voice = this.getBestVoice('female');
                        if (voice) {
                            utterance.voice = voice;
                        }

                        utterance.onend = () => {
                            if (this.aiState === 'speaking') {
                                this.aiState = 'listening';
                                this.startSpeechRecognition();
                            }
                        };
                        utterance.onerror = () => {
                            this.aiState = 'listening';
                        };

                        window.speechSynthesis.speak(utterance);
                    }
                },

                replayAiQuestion() {
                    this.askCurrentAiQuestion();
                },

                toggleUserMic() {
                    if (this.aiState === 'listening') {
                        this.stopSpeechRecognition();
                        this.aiState = 'idle';
                    } else {
                        this.stopAllAudio();
                        this.aiState = 'listening';
                        this.startSpeechRecognition();
                    }
                },

                startSpeechRecognition() {
                    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
                    if (!SpeechRecognition) return;

                    try {
                        if (this.recognitionInstance) {
                            this.recognitionInstance.stop();
                        }
                        this.recognitionInstance = new SpeechRecognition();
                        this.recognitionInstance.lang = 'en-US';
                        this.recognitionInstance.interimResults = true;
                        this.recognitionInstance.continuous = false;

                        this.recognitionInstance.onresult = (event) => {
                            const transcript = Array.from(event.results)
                                .map(result => result[0].transcript)
                                .join('');
                            this.userSpokenText = transcript;
                        };

                        this.recognitionInstance.onerror = (event) => {
                            console.log('Speech recognition notice:', event.error);
                        };

                        this.recognitionInstance.start();
                    } catch (e) {
                        console.log('Speech recognition not available:', e);
                    }
                },

                stopSpeechRecognition() {
                    if (this.recognitionInstance) {
                        try {
                            this.recognitionInstance.stop();
                        } catch (e) {}
                    }
                },

                nextAiQuestion() {
                    this.stopSpeechRecognition();
                    this.stopAllAudio();
                    if (this.currentAiQIdx < this.aiQuestions.length - 1) {
                        this.currentAiQIdx++;
                        this.askCurrentAiQuestion();
                    } else {
                        this.aiState = 'finished';
                        this.speakText("Congratulations! You have completed all the interview questions for this meeting. Wonderful job!", 'female');
                    }
                },

                restartAiInterview() {
                    this.stopSpeechRecognition();
                    this.stopAllAudio();
                    this.currentAiQIdx = 0;
                    this.userSpokenText = '';
                    this.aiState = 'idle';
                },

                // Recorder properties
                isRecording: false,
                mediaRecorder: null,
                audioChunks: [],
                audioUrl: null,
                recordingDuration: 0,
                timerInterval: null,

                async startRecording() {
                    try {
                        const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
                        this.mediaRecorder = new MediaRecorder(stream);
                        this.audioChunks = [];
                        this.recordingDuration = 0;

                        this.mediaRecorder.ondataavailable = (event) => {
                            if (event.data.size > 0) {
                                this.audioChunks.push(event.data);
                            }
                        };

                        this.mediaRecorder.onstop = () => {
                            const audioBlob = new Blob(this.audioChunks, { type: 'audio/webm' });
                            this.audioUrl = URL.createObjectURL(audioBlob);
                        };

                        this.mediaRecorder.start();
                        this.isRecording = true;

                        this.timerInterval = setInterval(() => {
                            this.recordingDuration++;
                        }, 1000);
                    } catch (err) {
                        alert('Izin mikrofon diperlukan untuk merekam suara: ' + err.message);
                    }
                },

                stopRecording() {
                    if (this.mediaRecorder && this.isRecording) {
                        this.mediaRecorder.stop();
                        this.isRecording = false;
                        clearInterval(this.timerInterval);
                    }
                }
            };
        };

        window.differentLivesGame = function differentLivesGame(gameData) {
            return {
                activeStudent: 'A',
                gameSubTab: 'my_routine', // 'my_routine', 'partner_routine', 'differences', 'all_cards', 'guide'
                timeStyle: 'british', // 'british', 'american'
                sentencePerson: 'you', // 'you', 'i', 'third', 'past'
                isZoomModalOpen: false,
                zoomModalTarget: 'cards', // 'cards' or 'guide'
                searchQuery: '',
                partnerScrambled: false,
                scrambledOrder: [],
                revealedPartnerCard: {},
                allCards: gameData.cards || [],
                cardMap: {},

                // Chosen card IDs for routine A & B
                routineA: (gameData.default_routine_a && gameData.default_routine_a.length > 0) ? [...gameData.default_routine_a] : [1, 2, 4, 6, 8, 9, 12, 14, 19, 22],
                routineB: (gameData.default_routine_b && gameData.default_routine_b.length > 0) ? [...gameData.default_routine_b] : [1, 2, 3, 21, 7, 10, 13, 16, 15, 18, 22],

                // Times mapping: cardId -> 'HH:MM'
                timesA: {},
                timesB: {},

                // Custom text for blank cards (23 & 24)
                customTexts: {
                    23: 'take an online English course',
                    24: 'walk the dog in the park'
                },

                init() {
                    // Populate cardMap and default times
                    this.allCards.forEach(c => {
                        this.cardMap[c.id] = c;
                        this.timesA[c.id] = c.default_time_a || '07:00';
                        this.timesB[c.id] = c.default_time_b || '07:30';
                    });

                    // Restore from localStorage
                    try {
                        const savedA = localStorage.getItem('TB_DIFF_LIVES_M2_A');
                        if (savedA) {
                            const pA = JSON.parse(savedA);
                            if (pA.routine && Array.isArray(pA.routine) && pA.routine.length > 0) this.routineA = pA.routine;
                            if (pA.times) Object.assign(this.timesA, pA.times);
                            if (pA.customTexts) Object.assign(this.customTexts, pA.customTexts);
                        }
                        const savedB = localStorage.getItem('TB_DIFF_LIVES_M2_B');
                        if (savedB) {
                            const pB = JSON.parse(savedB);
                            if (pB.routine && Array.isArray(pB.routine) && pB.routine.length > 0) this.routineB = pB.routine;
                            if (pB.times) Object.assign(this.timesB, pB.times);
                            if (pB.customTexts) Object.assign(this.customTexts, pB.customTexts);
                        }
                    } catch(e) {}

                    // Role lock enforcement
                    if (this.previewRole === 'student') {
                        this.activeStudent = this.assignedStudentRole || 'A';
                    }
                    if (this.$watch) {
                        this.$watch('previewRole', (val) => {
                            if (val === 'student') {
                                this.activeStudent = this.assignedStudentRole || 'A';
                                if (this.gameSubTab === 'guide') this.gameSubTab = 'my_routine';
                            }
                        });
                    }

                    // Listen to global admin event
                    window.addEventListener('set-different-lives-student', (e) => {
                        if (this.previewRole === 'admin' && e.detail) {
                            this.activeStudent = e.detail;
                        }
                    });

                    this.sortRoutines();
                    this.initScramble();
                },

                saveData() {
                    try {
                        localStorage.setItem('TB_DIFF_LIVES_M2_A', JSON.stringify({
                            routine: this.routineA,
                            times: this.timesA,
                            customTexts: this.customTexts
                        }));
                        localStorage.setItem('TB_DIFF_LIVES_M2_B', JSON.stringify({
                            routine: this.routineB,
                            times: this.timesB,
                            customTexts: this.customTexts
                        }));
                    } catch(e) {}
                },

                sortRoutines() {
                    this.routineA.sort((a, b) => (this.timesA[a] || '00:00').localeCompare(this.timesA[b] || '00:00'));
                    this.routineB.sort((a, b) => (this.timesB[a] || '00:00').localeCompare(this.timesB[b] || '00:00'));
                },

                initScramble() {
                    const partnerIds = this.getPartnerRoutine();
                    this.scrambledOrder = [...partnerIds].sort(() => Math.random() - 0.5);
                },

                toggleScramble() {
                    this.partnerScrambled = !this.partnerScrambled;
                    if (this.partnerScrambled) {
                        this.initScramble();
                    }
                },

                getMyRoutine() {
                    return (this.activeStudent === 'A') ? this.routineA : this.routineB;
                },

                getPartnerRoutine() {
                    return (this.activeStudent === 'A') ? this.routineB : this.routineA;
                },

                getMyTime(cardId) {
                    return (this.activeStudent === 'A') ? (this.timesA[cardId] || '07:00') : (this.timesB[cardId] || '07:30');
                },

                getPartnerTime(cardId) {
                    return (this.activeStudent === 'A') ? (this.timesB[cardId] || '07:30') : (this.timesA[cardId] || '07:00');
                },

                setCardTime(cardId, newTime, student = null) {
                    const st = student || this.activeStudent;
                    if (st === 'A') {
                        this.timesA[cardId] = newTime;
                    } else {
                        this.timesB[cardId] = newTime;
                    }
                    this.sortRoutines();
                    this.saveData();
                },

                adjustCardTime(cardId, deltaMinutes, student = null) {
                    const current = (student || this.activeStudent) === 'A' ? (this.timesA[cardId] || '07:00') : (this.timesB[cardId] || '07:30');
                    const parts = current.split(':');
                    let h = parseInt(parts[0], 10) || 0;
                    let m = parseInt(parts[1], 10) || 0;
                    let total = h * 60 + m + deltaMinutes;
                    if (total < 0) total += 24 * 60;
                    total = total % (24 * 60);
                    const nh = Math.floor(total / 60);
                    const nm = total % 60;
                    const newStr = String(nh).padStart(2, '0') + ':' + String(nm).padStart(2, '0');
                    this.setCardTime(cardId, newStr, student);
                },

                isInRoutine(cardId, student = null) {
                    const st = student || this.activeStudent;
                    const r = (st === 'A') ? this.routineA : this.routineB;
                    return r.includes(cardId);
                },

                toggleRoutineItem(cardId) {
                    let r = (this.activeStudent === 'A') ? this.routineA : this.routineB;
                    const idx = r.indexOf(cardId);
                    if (idx >= 0) {
                        if (r.length <= 3) {
                            alert('Jadwal harian minimal memiliki 3 kartu aktivitas!');
                            return;
                        }
                        r.splice(idx, 1);
                    } else {
                        r.push(cardId);
                    }
                    this.sortRoutines();
                    this.saveData();
                },

                // Natural British telling time
                toBritish(timeStr) {
                    if (!timeStr) return '';
                    const parts = timeStr.split(':');
                    const h = parseInt(parts[0], 10) || 0;
                    const m = parseInt(parts[1], 10) || 0;
                    const hours = ['', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine', 'ten', 'eleven', 'twelve'];
                    const h12 = (h % 12 === 0) ? 12 : (h % 12);
                    const nextH = (h12 % 12) + 1;
                    const hWord = hours[h12];
                    const nextWord = hours[nextH];

                    if (m === 0) return hWord + " o'clock";
                    if (m === 15) return "a quarter past " + hWord;
                    if (m === 30) return "half past " + hWord;
                    if (m === 45) return "a quarter to " + nextWord;
                    if (m === 5) return "five past " + hWord;
                    if (m === 10) return "ten past " + hWord;
                    if (m === 20) return "twenty past " + hWord;
                    if (m === 25) return "twenty-five past " + hWord;
                    if (m === 35) return "twenty-five to " + nextWord;
                    if (m === 40) return "twenty to " + nextWord;
                    if (m === 50) return "ten to " + nextWord;
                    if (m === 55) return "five to " + nextWord;
                    if (m < 30) return m + " minutes past " + hWord;
                    return (60 - m) + " minutes to " + nextWord;
                },

                // Natural American telling time
                toAmerican(timeStr) {
                    if (!timeStr) return '';
                    const parts = timeStr.split(':');
                    const h = parseInt(parts[0], 10) || 0;
                    const m = parseInt(parts[1], 10) || 0;
                    const hours = ['', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine', 'ten', 'eleven', 'twelve'];
                    const h12 = (h % 12 === 0) ? 12 : (h % 12);
                    const hWord = hours[h12];
                    if (m === 0) return hWord + " o'clock";
                    const ones = ['', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine', 'ten', 'eleven', 'twelve', 'thirteen', 'fourteen', 'fifteen', 'sixteen', 'seventeen', 'eighteen', 'nineteen'];
                    const tens = ['', '', 'twenty', 'thirty', 'forty', 'fifty'];
                    let mWord = '';
                    if (m < 10) {
                        mWord = 'oh-' + ones[m];
                    } else if (m < 20) {
                        mWord = ones[m];
                    } else {
                        mWord = tens[Math.floor(m / 10)] + (m % 10 !== 0 ? '-' + ones[m % 10] : '');
                    }
                    return hWord + ' ' + mWord;
                },

                // Clock hand rotation angles for SVG
                getClockAngles(timeStr) {
                    if (!timeStr) return { hDeg: 0, mDeg: 0 };
                    const parts = timeStr.split(':');
                    const h = parseInt(parts[0], 10) || 0;
                    const m = parseInt(parts[1], 10) || 0;
                    return {
                        hDeg: (h % 12) * 30 + m * 0.5,
                        mDeg: m * 6
                    };
                },

                // Build full sentence
                buildSentence(card, timeStr, person = null) {
                    if (!card) return '';
                    const p = person || this.sentencePerson;
                    const t = (this.timeStyle === 'british') ? this.toBritish(timeStr) : this.toAmerican(timeStr);
                    const actName = (card.id >= 23 && this.customTexts[card.id]) ? this.customTexts[card.id] : card.name;
                    
                    if (p === 'you') return 'You ' + actName + ' at ' + t + '.';
                    if (p === 'i') return 'I ' + actName + ' at ' + t + '.';
                    if (p === 'third') {
                        const tp = (card.id >= 23) ? actName + 's' : (card.third_person || (actName + 's'));
                        return 'He/She ' + tp + ' at ' + t + '.';
                    }
                    if (p === 'past') {
                        const pt = (card.id >= 23) ? actName : (card.past || actName);
                        return 'Yesterday, you ' + pt + ' at ' + t + '.';
                    }
                    return 'You ' + actName + ' at ' + t + '.';
                },

                // Play Audio with Web Speech API
                speakSentence(card, timeStr, person = null) {
                    const text = this.buildSentence(card, timeStr, person);
                    if (window.speechSynthesis) {
                        window.speechSynthesis.cancel();
                        const utt = new SpeechSynthesisUtterance(text);
                        utt.lang = (this.timeStyle === 'british') ? 'en-GB' : 'en-US';
                        utt.rate = 0.9;
                        window.speechSynthesis.speak(utt);
                    }
                },

                // Speak raw text
                speakRaw(text) {
                    if (window.speechSynthesis) {
                        window.speechSynthesis.cancel();
                        const utt = new SpeechSynthesisUtterance(text);
                        utt.lang = (this.timeStyle === 'british') ? 'en-GB' : 'en-US';
                        utt.rate = 0.9;
                        window.speechSynthesis.speak(utt);
                    }
                },

                getFilteredCards() {
                    if (!this.searchQuery) return this.allCards;
                    const q = this.searchQuery.toLowerCase().trim();
                    return this.allCards.filter(c => {
                        const name = c.name.toLowerCase();
                        const idName = (c.id_name || '').toLowerCase();
                        return name.includes(q) || idName.includes(q);
                    });
                }
            };
        };

        window.happyBirthdayGame = function happyBirthdayGame(gameData) {
            return {
                gameSubTab: 'my_present', // 'my_present', 'interview_log', 'all_cards', 'guide'
                dateStyle: 'uk', // 'uk' (the 28th of February), 'us' (February 28th)
                isZoomModalOpen: false,
                zoomModalTarget: 'cards', // 'cards', 'guide', 'language'
                allCards: gameData.cards || [],
                selectedCard: null,
                revealedGift: false,
                revealedCardGifts: {},
                isDrawing: false,

                // Custom Birthday creator
                showCustomCreator: false,
                customDate: {
                    month: 'February',
                    day: 28,
                    gift: 'a box of chocolates'
                },

                // Search log table: classmates asked
                searchLog: [],
                newLog: {
                    name: '',
                    month: 'February',
                    day: 28,
                    matched: false
                },

                monthsList: [
                    'January', 'February', 'March', 'April', 'May', 'June',
                    'July', 'August', 'September', 'October', 'November', 'December'
                ],

                init() {
                    if (this.allCards.length > 0) {
                        this.selectedCard = this.allCards[0];
                    }

                    // Restore from localStorage
                    try {
                        const savedLog = localStorage.getItem('TB_HAPPY_BIRTHDAY_M3_LOG');
                        if (savedLog) {
                            this.searchLog = JSON.parse(savedLog);
                        }
                        const savedCard = localStorage.getItem('TB_HAPPY_BIRTHDAY_M3_CARD');
                        if (savedCard) {
                            this.selectedCard = JSON.parse(savedCard);
                            if (this.selectedCard && this.selectedCard.image) {
                                this.selectedCard.image = this.selectedCard.image.split('?')[0] + '?v=color_v2';
                            }
                        }
                    } catch(e) {}
                },

                drawRandomCard() {
                    if (!this.allCards.length) return;
                    this.isDrawing = true;
                    this.revealedGift = false;
                    setTimeout(() => {
                        const rand = Math.floor(Math.random() * this.allCards.length);
                        this.selectedCard = this.allCards[rand];
                        try {
                            localStorage.setItem('TB_HAPPY_BIRTHDAY_M3_CARD', JSON.stringify(this.selectedCard));
                        } catch(e) {}
                        this.isDrawing = false;
                    }, 400);
                },

                selectCard(card) {
                    this.selectedCard = card;
                    this.revealedGift = false;
                    this.gameSubTab = 'my_present';
                    try {
                        localStorage.setItem('TB_HAPPY_BIRTHDAY_M3_CARD', JSON.stringify(this.selectedCard));
                    } catch(e) {}
                },

                toggleCardGift(id) {
                    this.revealedCardGifts[id] = !this.revealedCardGifts[id];
                },

                saveCustomCard() {
                    if (!this.customDate.month) return;
                    const ord = this.getOrdinalSuffix(this.customDate.day);
                    const dayNum = this.customDate.day + ord;
                    const card = {
                        id: 'custom_' + Date.now(),
                        image: '/images/speaking/happy_birthday/card_01.png?v=color_v2',
                        date: this.customDate.day + ' ' + this.customDate.month,
                        month: this.customDate.month,
                        day_num: dayNum,
                        date_uk: 'the ' + this.getSpokenOrdinal(this.customDate.day) + ' of ' + this.customDate.month,
                        date_us: this.customDate.month + ' ' + this.getSpokenOrdinal(this.customDate.day),
                        gift: this.customDate.gift || 'a mystery present',
                        gift_id: 'hadiah spesial pilihanmu',
                        gift_icon: '🎁',
                        question: 'When is your birthday?',
                        answer_in: "It's in " + this.customDate.month + ".",
                        answer_on_uk: "It's on the " + this.getSpokenOrdinal(this.customDate.day) + " of " + this.customDate.month + ".",
                        answer_on_us: "It's on " + this.customDate.month + " " + this.getSpokenOrdinal(this.customDate.day) + ".",
                        handover: "Happy Birthday! This present is for you. It's " + (this.customDate.gift || 'a mystery present') + "!",
                    };
                    this.selectedCard = card;
                    this.showCustomCreator = false;
                    this.revealedGift = false;
                    try {
                        localStorage.setItem('TB_HAPPY_BIRTHDAY_M3_CARD', JSON.stringify(this.selectedCard));
                    } catch(e) {}
                },

                addSearchLog() {
                    if (!this.newLog.name.trim()) return;
                    const ord = this.getOrdinalSuffix(this.newLog.day);
                    this.searchLog.unshift({
                        id: Date.now(),
                        name: this.newLog.name.trim(),
                        month: this.newLog.month,
                        day: this.newLog.day ? (this.newLog.day + ord) : '',
                        matched: this.newLog.matched
                    });
                    this.newLog.name = '';
                    this.newLog.matched = false;
                    this.persistLog();
                },

                removeLog(index) {
                    this.searchLog.splice(index, 1);
                    this.persistLog();
                },

                toggleMatch(index) {
                    this.searchLog[index].matched = !this.searchLog[index].matched;
                    this.persistLog();
                },

                persistLog() {
                    try {
                        localStorage.setItem('TB_HAPPY_BIRTHDAY_M3_LOG', JSON.stringify(this.searchLog));
                    } catch(e) {}
                },

                getOrdinalSuffix(d) {
                    const n = parseInt(d);
                    if (n % 100 >= 11 && n % 100 <= 13) return 'th';
                    switch (n % 10) {
                        case 1: return 'st';
                        case 2: return 'nd';
                        case 3: return 'rd';
                        default: return 'th';
                    }
                },

                getSpokenOrdinal(d) {
                    const words = {
                        1: 'first', 2: 'second', 3: 'third', 4: 'fourth', 5: 'fifth',
                        6: 'sixth', 7: 'seventh', 8: 'eighth', 9: 'ninth', 10: 'tenth',
                        11: 'eleventh', 12: 'twelfth', 13: 'thirteenth', 14: 'fourteenth', 15: 'fifteenth',
                        16: 'sixteenth', 17: 'seventeenth', 18: 'eighteenth', 19: 'nineteenth', 20: 'twentieth',
                        21: 'twenty-first', 22: 'twenty-second', 23: 'twenty-third', 24: 'twenty-fourth', 25: 'twenty-fifth',
                        26: 'twenty-sixth', 27: 'twenty-seventh', 28: 'twenty-eighth', 29: 'twenty-ninth', 30: 'thirtieth',
                        31: 'thirty-first'
                    };
                    return words[parseInt(d)] || d;
                },

                speak(text) {
                    if (window.speechSynthesis) {
                        window.speechSynthesis.cancel();
                        const utt = new SpeechSynthesisUtterance(text);
                        utt.lang = (this.dateStyle === 'uk') ? 'en-GB' : 'en-US';
                        utt.rate = 0.9;
                        window.speechSynthesis.speak(utt);
                    }
                }
            };
        };

        window.whoWasFirstGame = function whoWasFirstGame(gameData) {
            return {
                gameSubTab: 'podium', // 'podium', 'worksheet', 'logic_guide', 'language'
                viewMode: 'worksheet', // 'worksheet', 'solution', 'scan'
                isZoomModalOpen: false,
                zoomModalTarget: 'worksheet', // 'worksheet', 'solution', 'scan'
                runners: gameData.runners || [],
                logicSteps: gameData.logic_steps || [],
                assets: gameData.assets || {},
                structures: gameData.structures || {},

                // 8 Podium slots (index 0..7 for 1st..8th)
                slots: [null, null, null, null, null, null, null, null],
                selectedRunnerId: null,

                // Audio
                isSpeaking: false,
                currentAudioText: null,

                // Validation
                checked: false,
                isAllCorrect: false,
                score: 0,
                feedbackMessage: '',

                init() {
                    try {
                        const saved = localStorage.getItem('TB_WHO_WAS_FIRST_SLOTS');
                        if (saved) {
                            const parsed = JSON.parse(saved);
                            if (Array.isArray(parsed) && parsed.length === 8) {
                                this.slots = parsed;
                            }
                        }
                    } catch(e) {}
                },

                selectRunner(runner) {
                    if (this.selectedRunnerId === runner.id) {
                        this.selectedRunnerId = null;
                    } else {
                        this.selectedRunnerId = runner.id;
                    }
                },

                placeRunnerInSlot(slotIndex) {
                    if (!this.selectedRunnerId) {
                        if (this.slots[slotIndex]) {
                            this.slots[slotIndex] = null;
                            this.checked = false;
                            this.saveSlots();
                        }
                        return;
                    }

                    const runner = this.runners.find(r => r.id === this.selectedRunnerId);
                    if (!runner) return;

                    // If runner is in another slot, clear old slot
                    const existingSlot = this.slots.findIndex(s => s && s.id === runner.id);
                    if (existingSlot !== -1 && existingSlot !== slotIndex) {
                        this.slots[existingSlot] = null;
                    }

                    this.slots[slotIndex] = runner;
                    this.selectedRunnerId = null;
                    this.checked = false;
                    this.saveSlots();
                },

                removeFromSlot(slotIndex) {
                    this.slots[slotIndex] = null;
                    this.checked = false;
                    this.saveSlots();
                },

                clearAllSlots() {
                    this.slots = [null, null, null, null, null, null, null, null];
                    this.selectedRunnerId = null;
                    this.checked = false;
                    this.isAllCorrect = false;
                    this.score = 0;
                    this.feedbackMessage = '';
                    this.saveSlots();
                },

                saveSlots() {
                    try {
                        localStorage.setItem('TB_WHO_WAS_FIRST_SLOTS', JSON.stringify(this.slots));
                    } catch(e) {}
                },

                fillSolution() {
                    const sorted = [...this.runners].sort((a, b) => a.rank - b.rank);
                    this.slots = sorted;
                    this.checked = true;
                    this.isAllCorrect = true;
                    this.score = 8;
                    this.feedbackMessage = 'Semua urutan pelari 100% tepat! Stripy = 1st, Spotted = 2nd, Lightning = 3rd, White = 4th, Black = 5th, No.5 = 6th, No.10 = 7th, Cat = 8th 🎉';
                    this.saveSlots();
                },

                checkAnswer() {
                    let correctCount = 0;
                    let placedCount = 0;

                    for (let i = 0; i < 8; i++) {
                        const runner = this.slots[i];
                        if (runner) {
                            placedCount++;
                            const targetRank = i + 1;
                            // Special tie condition: rank 6 & rank 7 (No.5 and No.10) finished with identical times
                            if (runner.rank === targetRank || ((targetRank === 6 || targetRank === 7) && (runner.rank === 6 || runner.rank === 7))) {
                                correctCount++;
                            }
                        }
                    }

                    this.checked = true;
                    this.score = correctCount;
                    this.isAllCorrect = (correctCount === 8);

                    if (this.isAllCorrect) {
                        this.feedbackMessage = 'Luar biasa! 100% Sempurna! Anda berhasil memecahkan teka-teki urutan balapan dengan benar!';
                        if (typeof confetti === 'function') {
                            confetti({ particleCount: 100, spread: 70, origin: { y: 0.6 } });
                        }
                    } else {
                        this.feedbackMessage = `Anda menempatkan ${placedCount} pelari (${correctCount} benar dari 8). Silakan baca petunjuk kembali dan coba lagi!`;
                    }
                },

                speak(text) {
                    if (!window.speechSynthesis) return;
                    window.speechSynthesis.cancel();
                    const utt = new SpeechSynthesisUtterance(text);
                    utt.lang = 'en-US';
                    utt.rate = 0.92;
                    this.isSpeaking = true;
                    this.currentAudioText = text;
                    utt.onend = () => {
                        this.isSpeaking = false;
                        this.currentAudioText = null;
                    };
                    utt.onerror = () => {
                        this.isSpeaking = false;
                        this.currentAudioText = null;
                    };
                    window.speechSynthesis.speak(utt);
                },

                isRunnerPlaced(runnerId) {
                    return this.slots.some(s => s && s.id === runnerId);
                }
            };
        };

        window.whereAreMyGlassesGame = function whereAreMyGlassesGame(gameData) {
            return {
                gameSubTab: 'my_card', // 'my_card', 'practice', 'room_map', 'log', 'guide'
                roles: gameData.roles || {},
                activeRoleId: 'dad',
                selectedLostItem: null,
                foundStatus: {},
                roomMode: 'color', // 'color', 'scan'
                isZoomModalOpen: false,
                zoomModalTarget: 'room_color',

                // Practice simulator
                practiceRole: 'dad',
                practiceItemIndex: 0,
                revealAnswer: false,

                // Classroom search log
                familyLog: [],
                newLog: {
                    classmateName: '',
                    familyRole: 'Jenny',
                    itemAsked: 'hairbrush',
                    prepositionUsed: 'on',
                    locationFound: 'on the floor between chair and TV',
                    isFound: true
                },

                init() {
                    const savedRole = localStorage.getItem('TB_WHERE_GLASSES_ROLE');
                    if (savedRole && this.roles[savedRole]) {
                        this.activeRoleId = savedRole;
                    }
                    try {
                        const savedFound = localStorage.getItem('TB_WHERE_GLASSES_FOUND');
                        if (savedFound) {
                            this.foundStatus = JSON.parse(savedFound);
                        }
                        const savedLog = localStorage.getItem('TB_WHERE_GLASSES_LOG');
                        if (savedLog) {
                            this.familyLog = JSON.parse(savedLog);
                        }
                    } catch(e) {}

                    this.initSelectedLostItem();
                },

                initSelectedLostItem() {
                    const r = this.getCurrentRole();
                    if (r && r.lost_items && r.lost_items.length > 0) {
                        this.selectedLostItem = r.lost_items[0];
                    }
                },

                getCurrentRole() {
                    return this.roles[this.activeRoleId] || this.roles['dad'] || {};
                },

                selectRole(roleId) {
                    if (this.roles[roleId]) {
                        this.activeRoleId = roleId;
                        this.initSelectedLostItem();
                        try {
                            localStorage.setItem('TB_WHERE_GLASSES_ROLE', roleId);
                        } catch(e) {}
                    }
                },

                randomRole() {
                    const keys = Object.keys(this.roles);
                    if (keys.length) {
                        const r = keys[Math.floor(Math.random() * keys.length)];
                        this.selectRole(r);
                    }
                },

                selectLostItem(item) {
                    this.selectedLostItem = item;
                },

                toggleFound(itemId) {
                    this.foundStatus[itemId] = !this.foundStatus[itemId];
                    try {
                        localStorage.setItem('TB_WHERE_GLASSES_FOUND', JSON.stringify(this.foundStatus));
                    } catch(e) {}
                },

                isFound(itemId) {
                    return !!this.foundStatus[itemId];
                },

                getFoundCount() {
                    const items = (this.getCurrentRole().lost_items) || [];
                    return items.filter(i => this.isFound(i.id)).length;
                },

                resetFoundStatus() {
                    const items = (this.getCurrentRole().lost_items) || [];
                    items.forEach(i => {
                        this.foundStatus[i.id] = false;
                    });
                    try {
                        localStorage.setItem('TB_WHERE_GLASSES_FOUND', JSON.stringify(this.foundStatus));
                    } catch(e) {}
                },

                addFamilyLog() {
                    if (!this.newLog.locationFound.trim()) return;
                    this.familyLog.unshift({
                        id: Date.now(),
                        classmateName: this.newLog.classmateName.trim() || 'Teman Sekelas',
                        familyRole: this.newLog.familyRole,
                        itemAsked: this.newLog.itemAsked,
                        prepositionUsed: this.newLog.prepositionUsed,
                        locationFound: this.newLog.locationFound.trim(),
                        isFound: this.newLog.isFound
                    });
                    this.newLog.locationFound = '';
                    this.persistFamilyLog();
                },

                removeFamilyLog(idx) {
                    this.familyLog.splice(idx, 1);
                    this.persistFamilyLog();
                },

                persistFamilyLog() {
                    try {
                        localStorage.setItem('TB_WHERE_GLASSES_LOG', JSON.stringify(this.familyLog));
                    } catch(e) {}
                },

                openZoomModal(target) {
                    this.zoomModalTarget = target;
                    this.isZoomModalOpen = true;
                },

                speak(text) {
                    if (window.speechSynthesis) {
                        window.speechSynthesis.cancel();
                        const utt = new SpeechSynthesisUtterance(text);
                        utt.lang = 'en-GB';
                        utt.rate = 0.9;
                        window.speechSynthesis.speak(utt);
                    }
                }
            };
        };

        window.weddingPhotosGame = function weddingPhotosGame() {
            return {
                gameTab: 'worksheet', // 'worksheet', 'student_a', 'student_b', 'phrases', 'guide'
                selectedGroupPreview: null, // group id whose members are currently revealed in the admin bar
                photoMode: 'color', // 'color', 'sketch'
                activeModal: null,
                inputs: {
                    // Bride's side (Family A)
                    joe: '',
                    elsie: '',
                    tom: '',
                    jess: '',
                    pete: '',
                    sue: '',
                    sam: '',
                    mike: '',
                    // Groom's side (Family B)
                    jim: '',
                    betty: '',
                    al: '',
                    jane: '',
                    ben: '',
                    liz: '',
                    beth: '',
                    john: ''
                },
                solution: {
                    joe: 'Joe',
                    elsie: 'Elsie',
                    tom: 'Tom',
                    jess: 'Jess',
                    pete: 'Pete',
                    sue: 'Sue',
                    sam: 'Sam',
                    mike: 'Mike',
                    jim: 'Jim',
                    betty: 'Betty',
                    al: 'Al',
                    jane: 'Jane',
                    ben: 'Ben',
                    liz: 'Liz',
                    beth: 'Beth',
                    john: 'John'
                },
                isSubmitted: false,
                score: 0,
                showSolutions: false,
                channel: null,
                pollTimer: null,
                saveDebounceTimer: null,
                
                init() {
                    if (this.previewRole === 'student') {
                        if (this.gameTab === 'student_b' && this.assignedStudentRole === 'A') this.gameTab = 'student_a';
                        if (this.gameTab === 'student_a' && this.assignedStudentRole === 'B') this.gameTab = 'student_b';
                        if (this.gameTab === 'guide') this.gameTab = 'worksheet';
                    }
                    if (this.$watch) {
                        this.$watch('previewRole', (val) => {
                            if (val === 'student') {
                                if (this.gameTab === 'student_b' && this.assignedStudentRole === 'A') this.gameTab = 'student_a';
                                if (this.gameTab === 'student_a' && this.assignedStudentRole === 'B') this.gameTab = 'student_b';
                                if (this.gameTab === 'guide') this.gameTab = 'worksheet';
                                this.showSolutions = false;
                            }
                        });
                    }

                    // 1. Load initial answers from localStorage
                    try {
                        const saved = localStorage.getItem('TB_WEDDING_PHOTOS_M5');
                        if (saved) {
                            const parsed = JSON.parse(saved);
                            Object.keys(this.inputs).forEach(k => {
                                if (parsed[k] !== undefined && parsed[k] !== '') this.inputs[k] = parsed[k];
                            });
                        }
                    } catch(e) {}

                    // 2. Real-time instant BroadcastChannel across tabs/windows (0ms latency)
                    try {
                        if (typeof window !== 'undefined' && 'BroadcastChannel' in window) {
                            this.channel = new BroadcastChannel('TB_WEDDING_PHOTOS_M5');
                            this.channel.onmessage = (event) => {
                                if (event.data) {
                                    if (event.data.type === 'RESET') {
                                        Object.keys(this.inputs).forEach(k => this.inputs[k] = '');
                                        this.isSubmitted = false;
                                        this.score = 0;
                                    } else if (event.data.inputs) {
                                        this.mergeInputs(event.data.inputs);
                                    }
                                }
                            };
                        }
                    } catch(e) {}

                    // 3. Fallback cross-tab storage listener
                    window.addEventListener('storage', (e) => {
                        if (e.key === 'TB_WEDDING_PHOTOS_M5' && e.newValue) {
                            try {
                                const parsed = JSON.parse(e.newValue);
                                this.mergeInputs(parsed);
                            } catch(err) {}
                        }
                    });

                    // 4. Server-side sync for cross-device / paired student synchronization
                    this.fetchServerDraft();
                    this.pollTimer = setInterval(() => {
                        this.fetchServerDraft();
                    }, 2000);

                    // 5. Bi-directional sync with global floating bar dock
                    window.addEventListener('set-wedding-tab', (e) => {
                        if (e.detail) {
                            this.gameTab = e.detail;
                        }
                    });
                    if (this.$watch) {
                        this.$watch('gameTab', (val) => {
                            window.dispatchEvent(new CustomEvent('wedding-tab-updated', { detail: val }));
                        });
                    }
                },

                mergeInputs(newInputs) {
                    if (!newInputs || typeof newInputs !== 'object') return;
                    const activeEl = document.activeElement;
                    Object.keys(this.inputs).forEach(k => {
                        if (newInputs[k] !== undefined) {
                            // Avoid overwriting the field the user is currently actively typing in
                            const isFocused = activeEl && activeEl.getAttribute('x-model') === `inputs.${k}`;
                            if (!isFocused && newInputs[k] !== this.inputs[k]) {
                                this.inputs[k] = newInputs[k];
                            }
                        }
                    });
                },

                saveToStorage() {
                    // 1. Save to local storage
                    try {
                        localStorage.setItem('TB_WEDDING_PHOTOS_M5', JSON.stringify(this.inputs));
                    } catch(e) {}

                    // 2. Broadcast immediately to Student B / other tabs
                    try {
                        if (this.channel) {
                            this.channel.postMessage({ type: 'INPUT_UPDATE', inputs: this.inputs });
                        }
                    } catch(e) {}

                    // 3. Debounced server autosave
                    clearTimeout(this.saveDebounceTimer);
                    this.saveDebounceTimer = setTimeout(() => {
                        this.saveServerDraft();
                    }, 400);
                },

                saveServerDraft() {
                    try {
                        const url = '{{ route("assignments.speaking.meeting.draft", ["level" => $level, "meeting" => $meetingNumber]) }}';
                        const token = document.querySelector('meta[name="csrf-token"]')?.getAttribute('content') || '{{ csrf_token() }}';
                        fetch(url, {
                            method: 'POST',
                            headers: {
                                'Content-Type': 'application/json',
                                'X-CSRF-TOKEN': token,
                                'Accept': 'application/json'
                            },
                            body: JSON.stringify({ inputs: this.inputs })
                        }).catch(() => {});
                    } catch(e) {}
                },

                fetchServerDraft() {
                    try {
                        const url = '{{ route("assignments.speaking.meeting.draft.get", ["level" => $level, "meeting" => $meetingNumber]) }}';
                        fetch(url, {
                            headers: { 'Accept': 'application/json' }
                        })
                        .then(res => res.json())
                        .then(data => {
                            if (data && data.success && data.answers && typeof data.answers === 'object') {
                                this.mergeInputs(data.answers);
                                try {
                                    localStorage.setItem('TB_WEDDING_PHOTOS_M5', JSON.stringify(this.inputs));
                                } catch(e) {}
                            }
                        })
                        .catch(() => {});
                    } catch(e) {}
                },

                checkAnswers() {
                    this.isSubmitted = true;
                    let correctCount = 0;
                    let total = Object.keys(this.solution).length;
                    
                    Object.keys(this.solution).forEach(k => {
                        let userVal = (this.inputs[k] || '').trim().toLowerCase();
                        let solVal = this.solution[k].toLowerCase();
                        if (userVal === solVal) {
                            correctCount++;
                        }
                    });
                    
                    this.score = Math.round((correctCount / total) * 100);
                    this.playFeedbackAudio(this.score >= 70);
                },
                resetWorksheet() {
                    if (confirm('Apakah Anda yakin ingin mengosongkan semua isian nama?')) {
                        Object.keys(this.inputs).forEach(k => this.inputs[k] = '');
                        this.isSubmitted = false;
                        this.score = 0;
                        this.showSolutions = false;
                        this.saveToStorage();
                        try {
                            if (this.channel) {
                                this.channel.postMessage({ type: 'RESET' });
                            }
                        } catch(e) {}
                    }
                },
                isFieldCorrect(field) {
                    if (!this.isSubmitted) return null;
                    let userVal = (this.inputs[field] || '').trim().toLowerCase();
                    let solVal = this.solution[field].toLowerCase();
                    return userVal === solVal;
                },
                playFeedbackAudio(isGood) {
                    try {
                        const ctx = new (window.AudioContext || window.webkitAudioContext)();
                        const osc = ctx.createOscillator();
                        const gain = ctx.createGain();
                        osc.connect(gain);
                        gain.connect(ctx.destination);
                        
                        if (isGood) {
                            osc.frequency.setValueAtTime(523.25, ctx.currentTime); // C5
                            osc.frequency.setValueAtTime(659.25, ctx.currentTime + 0.1); // E5
                            osc.frequency.setValueAtTime(783.99, ctx.currentTime + 0.2); // G5
                            gain.gain.setValueAtTime(0.2, ctx.currentTime);
                            gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.45);
                            osc.start(ctx.currentTime);
                            osc.stop(ctx.currentTime + 0.45);
                        } else {
                            osc.frequency.setValueAtTime(220, ctx.currentTime);
                            osc.frequency.setValueAtTime(180, ctx.currentTime + 0.12);
                            gain.gain.setValueAtTime(0.25, ctx.currentTime);
                            gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.4);
                            osc.start(ctx.currentTime);
                            osc.stop(ctx.currentTime + 0.4);
                        }
                    } catch(e) {}
                }
            };
        };
    </script>
</head>
